const body = $input.first().json.body || $input.first().json;

const collaboratorId = body.collaboratorId;
const periodo = body.periodo;
const anno = body.anno;
const cuatrimestre = body.cuatrimestre;
const collaboratoreName = body.collaboratoreName;

if (!collaboratorId || !periodo || !anno || !cuatrimestre || !collaboratoreName) {
  throw new Error('Parametri mancanti: collaboratorId, periodo, anno, cuatrimestre, collaboratoreName obbligatori');
}

return [{ json: { collaboratorId, periodo, anno, cuatrimestre, collaboratoreName } }];

const binaryData = $input.first().binary.data;
const jsonStr = Buffer.from(binaryData.data, 'base64').toString('utf8').replace(/^=/, '');
const bufferData = JSON.parse(jsonStr);

const inputData = $('Valida Input').first().json;

return [{ json: {
  ...bufferData,
  collaboratorId: inputData.collaboratorId,
  periodo: inputData.periodo
}}];

const obiettivi = $input.first().json.ObjectivePlan;
const buffer = $('Leggi Buffer Qlik').first().json;

const invoiced = buffer.invoiced;
const soglie = obiettivi.ObjectiveThreshold.sort((a, b) => a.ObjectiveThresholdRevenueValue - b.ObjectiveThresholdRevenueValue);

let premioTotale = 0;
let bonusCurrency = soglie[0]?.ObjectiveThresholdBonusCurrency || 'COP';
let dettaglio = [];

for (const soglia of soglie) {
  const threshold = soglia.ObjectiveThresholdRevenueValue;
  const bonus = soglia.ObjectiveThresholdBonusValue;
  const tipo = soglia.ObjectiveThresholdType;

  let raggiunta = false;
  if (tipo === 'si_alcanza' && invoiced >= threshold) raggiunta = true;
  if (tipo === 'adicionalmente' && invoiced >= threshold) raggiunta = true;
  if (tipo === 'adicionalmente_mayor' && invoiced > threshold) raggiunta = true;

  if (raggiunta) {
    premioTotale += bonus;
    dettaglio.push(`${tipo}: €${threshold} → +${bonusCurrency} ${bonus}`);
  }
}

return [{ json: {
  ...buffer,
  pianoPremio: obiettivi.ObjectivePlanName,
  invoiced,
  premioTotale,
  bonusCurrency,
  dettaglio,
  soglie
}}];

const raw = $input.first().binary.data.data;
const profileData = JSON.parse(Buffer.from(raw, 'base64').toString('utf8'));

let previousData;
try {
  previousData = $('Somma Premio Filiale').first().json;
} catch (e) {
  previousData = $('Premio Filiale Zero').first().json;
}

return [{ json: { ...previousData, ...profileData } }];

const binaryData = $input.first().binary.data;
const jsonStr = Buffer.from(binaryData.data, 'base64').toString('utf8').replace(/^=/, '');
const bufferFiliale = JSON.parse(jsonStr);
const premioBase = $('Calcola Premio').first().json;
const buffQlik = $('Leggi Buffer Qlik').first().json;

const premioTotale = Number(premioBase.premioTotale) || 0;

return [{ json: {
  ...premioBase,
  imagenFileId: buffQlik.imagenFileId || null,
  valoreTotaleFiliale: 0,
  premioFiliale: 0,
  premioTotaleConFiliale: premioTotale
}}];

const premioBase = $('Calcola Premio').first().json;
const buffQlik = $('Leggi Buffer Qlik').first().json;

const premioTotale = Number(premioBase.premioTotale) || 0;

return [{ json: {
  ...premioBase,
  imagenFileId: buffQlik.imagenFileId || null,
  valoreTotaleFiliale: 0,
  premioFiliale: 0,
  premioTotaleConFiliale: premioTotale
}}];

const item = $input.first();
const binary = item.binary?.data;

if (!binary) {
  return [{ json: { ...item.json, imagenBase64: null, imagenMimeType: null } }];
}

const imagenBase64 = binary.data; // già base64 in n8n binary
const imagenMimeType = binary.mimeType || 'image/png';

return [{ json: { ...item.json, imagenBase64, imagenMimeType } }];

const data = $json;

// Dati base
const collaboratore = data.collaboratore || '';
const paese = data.paese || '';
const paeseSupabase = data.paeseSupabase || '';
const cuatrimestre = data.cuatrimestre || '';
const anno = data.anno || new Date().getFullYear();
const ruolo = data.collaboratorTypeName || '';

// Premio individuale
const premioTotale = data.premioTotale || 0;
const bonusCurrency = data.bonusCurrency || '';
const soglie = data.soglie || [];

// Premio filiale
const premioFiliale = data.premioFiliale || 0;
const valoreTotaleFiliale = data.valoreTotaleFiliale || 0;
const premioTotaleConFiliale = data.premioTotaleConFiliale || premioTotale;

// Formattazione numeri
const fmt = (n, decimals = 2) => Number(n).toLocaleString('es-ES', { minimumFractionDigits: decimals, maximumFractionDigits: decimals });

// Righe tabella soglie individuale
const righeSoglie = soglie.map(s => `
  <tr>
    <td>${s.ObjectiveThresholdType}</td>
    <td>${s.ObjectiveThresholdRevenueCurrency} ${fmt(s.ObjectiveThresholdRevenueValue)}</td>
    <td>${s.ObjectiveThresholdBonusCurrency} ${fmt(s.ObjectiveThresholdBonusValue)}</td>
  </tr>
`).join('');

const imagenBase64 = data.imagenBase64 || '';
const imagenMimeType = data.imagenMimeType || 'image/png';

// Logo aziendale (base64 embedded, stessa immagine usata dal legacy)
const LOGO_B64 = '';

// Intestazione azienda: SOLO se paeseSupabase è esplicitamente uno dei tre paesi validi.
// Nessun default automatico — se non c'è match, va solo il logo, senza dati aziendali.
const aziende = {
  'MEXICO': {
    nome: 'Unox Mexico S. de R.L. de C.V.',
    indirizzo: 'Av. Santa Fe, 170, Int. 6-4-12',
    citta: 'Lomas de Santa Fe, 01210 Ciudad de Mexico, Mexico',
    fiscal: 'RFC: UME1508269H3',
    contatto: 'info.mx@unox.com'
  },
  'MÉXICO': null, // placeholder per normalizzazione sotto
  'COLOMBIA': {
    nome: 'UNOX COLOMBIA S.A.S.',
    indirizzo: 'Cr 16 No. 97 46 P 8',
    citta: 'Bogotá D.C., Colombia',
    fiscal: 'NIT 901.453.891-8',
    contatto: 'info.co@unox.com'
  },
  'ITALIA': {
    nome: 'Unox S.p.A.',
    indirizzo: 'Via Majorana 22',
    citta: '35010 Cadoneghe PD – Italy',
    fiscal: 'Tel. +39 049 86.57.511 · Fax. +39 049 86.57.555',
    contatto: 'www.unox.com'
  }
};

// Normalizzazione accent-insensitive per il lookup (coerente col fix già fatto in Inbox Processor)
const normalizzaPaese = (s) => (s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .trim().toUpperCase();

const paeseKey = normalizzaPaese(paeseSupabase);
const mappaNormalizzata = { 'MEXICO': aziende['MEXICO'], 'COLOMBIA': aziende['COLOMBIA'], 'ITALIA': aziende['ITALIA'] };
const azienda = mappaNormalizzata[paeseKey] || null;

const headerInfoHtml = azienda ? `
  <div class="header-info">
    <strong>${azienda.nome}</strong>
    <p>${azienda.indirizzo}</p>
    <p>${azienda.citta}</p>
    <p>${azienda.fiscal}</p>
    <p>${azienda.contatto}</p>
  </div>
` : '';

const html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body { font-family: Arial, sans-serif; margin: 40px; color: #1a1a1a; font-size: 12px; }
  .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 24px; }
  .header-logo img { width: 180px; }
  .header-info { text-align: right; }
  .header-info strong { font-size: 13px; }
  .header-info p { margin: 2px 0; }
  h1 { font-size: 20px; margin-bottom: 4px; }
  .highlight { background: #ffe066; padding: 2px 6px; font-weight: bold; }
  .section-title { font-weight: bold; margin-top: 24px; margin-bottom: 8px; }
  table { border-collapse: collapse; width: 100%; margin-bottom: 16px; }
  th, td { border: 1px solid #999; padding: 6px 10px; text-align: center; font-size: 12px; }
  th { background: #1a1a1a; color: white; }
  .qlik-image { max-width: 100%; margin-top: 20px; border: 1px solid #ccc; }
  .firma { margin-top: 60px; font-size: 13px; }
</style>
</head>
<body>
  <div class="header">
    <div class="header-logo">
      <img src="data:image/png;base64,${LOGO_B64}" />
    </div>
    ${headerInfoHtml}
  </div>

  <h1>${collaboratore}: Resultado ${cuatrimestre} ${anno} ${ruolo ? '– ' + ruolo : ''}</h1>

  <p>Premio bruto previsto: <span class="highlight">${bonusCurrency} ${fmt(premioTotale, 0)}</span></p>

  <div class="section-title">Detalle Individual – ${paese}</div>
  <table>
    <tr><th>Umbral</th><th>Facturación (umbral)</th><th>Premio</th></tr>
    ${righeSoglie}
  </table>

  ${premioFiliale > 0 ? `
  <div class="section-title">Premio Filial</div>
  <p>Premio filial correspondiente a ${paese}: <span class="highlight">${bonusCurrency} ${fmt(valoreTotaleFiliale, 0)}</span></p>
  ` : ''}

  <div class="section-title">Total</div>
  <p><span class="highlight">${bonusCurrency} ${fmt(premioTotaleConFiliale, 0)}</span></p>

  ${imagenBase64 ? `
  <div class="section-title">Fuente Qlik</div>
  <img class="qlik-image" src="data:${imagenMimeType};base64,${imagenBase64}" />
  ` : ''}

  <div class="firma">
    <p>${collaboratore}</p>
    <p>Firma de reconocimiento y aceptación</p>
    ${ruolo ? `<p>${ruolo}</p>` : ''}
  </div>
</body>
</html>
`;

return [{
  json: { ...data, html },
  binary: {
    html: {
      data: Buffer.from(html).toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    }
  }
}];
